        StaticItem("Elderwood Ring", "This ring is woven through druidic magic from\nElderwood. The ring is three distinct strands, taken\nbirch, woven into an intricate pattern, the band giving\na very slight feeling of natural energy, the wood still\nliving and sustained through a powerful imbuement.", "minecraft:wooden_button", ""),
        StaticItem("Arnold's Animals Voucher", "A voucher that let's you\nredeem for one item at\nArnold's Animals.\n*Moderator Approved*\nMorsmordre approved this item.", "minecraft:paper", ""),
        StaticItem("A Bouncy Ball!", "Boing!\n*Moderator Approved*\nWretched approved this item.", "minecraft:slime_ball", ""),
        StaticItem("Siren's Tear", "A brilliant necklace forged of sterling silver links, with a single\nexquisitely cut teardrop aquamarine beryl wrapped with gold leaves.\nThispiece seems to have originated from the South.\nNote: Not actually tears of a Siren, do not drink!", "minecraft:prismarine_crystals", ""),
