        StaticItem("Giant Pearl", "A large fist sized pearl that gleams a proud\nsilver tint. If held into direct sunlight, it\nwould emit a soft rainbow reflection in a\nsmall radius around the holder. Probably\nworth a hefty sum of minas due to its size!\n★Event Actor Approved★\nSigned by ymbninjakiller.", "minecraft:snowball", ""),
