        StaticItem("Cute Orc Easter Egg", "", "minecraft:egg", ""),
        StaticItem("YoYo", "This piece of wood consists of a pair of joined discs\nwith a deep groove between them in which a string is attached and wound.\nThe YoYo would be capible of being spun downward and upward alternately.\n*Moderator Approved*\nFyaa approved this item.", "minecraft:stone_button", ""),
        StaticItem("A Folded Note", "A handwritten letter that reads \"Thank you\nfor the pie, it was delicious.", "minecraft:paper", ""),
        StaticItem("The Shield of House Yar", "An iron tower shield once wielded by Lord\nRakim Yar. At the center of the shield is an\neagle holding a snake with its beak and\nrestraining it with its talons.\n★Event Actor Approved★\nSigned by Shady_Tales.", "minecraft:shield", ""),
        StaticItem("-+- THE BLADE OF HALLOWVALE -+-", "A blue-steel longsword with an emerald\nembedded in the butt of the hilt. It is\nblessed by Xan Paladinism magic, modestly\neffective on the undead and unholy. It was\nonce wielded by an infamous monster hunter.\n★Game Moderator Approved★\nSigned by Zhulik.\nWhen in main hand:\n-2.4 Attack Speed\n+7 Attack Damage\n+29% Attack Damage", "minecraft:diamond_sword", ""),
        StaticItem("A Set of Orc Tusks", "The tusks seem to have been roughly cut from\nthe mouth of the victim.\n★Game Moderator Approved★\nSigned by Josh3738.", "minecraft:bone_block", ""),
