        StaticItem("Memoir of Grok", "A sturdy handmade staff with the name 'Grok\nengraved into the shaft to honor a fallen\nfriend.\n★Game Moderator Approved★\nSigned by Finalhazard.", "minecraft:iron_hoe", ""),
        StaticItem("The Pumpkin Prophet's Piece", "The cranium of a fallen druid, a grand\nskeletal comrade of yore. Battle brother to\nall of skelekind.\n★Event Actor Approved★\nSigned by AcidGoosey.", "minecraft:skull", ""),
