        StaticItem("Monkey Plushie", "This soft plushy has 'NMS' embroidered on the\nright ear, an authentic souvenir from the\nHorse Olympics Festival.\n★Game Moderator Approved★\nSigned by ShadowedOblivion.", "minecraft:skull", ""),
        StaticItem("Horse Plushie", "This soft plushy has 'NMS' embroidered on the\nright ear, an authentic souvenir from the\nHorse Olympics Festival.\n★Game Moderator Approved★\nSigned by ShadowedOblivion.", "minecraft:skull", ""),
        StaticItem("Embroidered Saddle", "This saddle is made from finely tanned\nleather. It has sewn embroidery and small\ngems embedded into the leather with NMS sewn\nby the rear.\n★Game Moderator Approved★\nSigned by ShadowedOblivion.", "minecraft:saddle", ""),
        StaticItem("Copper Cup", "A copper trophy cup with a plaque at the\nbase. \"3rd Place Winner of The Jumping\nCompetition. Horse Olympics, 1581.\n★Game Moderator Approved★\nSigned by ShadowedOblivion.", "minecraft:skull", ""),
