    private fun _AXIOS_ASUL_6(): List<StaticItem> = listOf(
        StaticItem("Magical Michael's Traveling Band Shirt", "A t-shirt handed out for\nattending the Felsen Show.\nThe shirt when worn feels\nquite magical!\n★Game Moderator Approved★\nSigned by Wrynn.", "minecraft:leather_chestplate", ""),
        StaticItem("Toy Sword", "This sword is wooden, clearly\nnot designed for actual warfare. However,\nit might be of fun for a child to play with.\n★Game Moderator Approved★\nSigned by Wrynn.", "minecraft:wooden_sword", ""),
        StaticItem("Ivy", "This sword is forged with hard steel,\na pattern of thorns engraved onto it.\n*Moderator Approved*\nImCookiie approved this item.", "minecraft:iron_sword", ""),
        StaticItem("Rusted Blade", "Gods, these things have been sitting around for ages!\" - A wandering scholar.\n*Moderator Approved*\nWrynn approved this item.", "minecraft:stone_sword", ""),
        StaticItem("Stinging Blade", "A crudely made dagger with an odd hue to it.\nIf this dagger were to cut a mortal, it would cause\na strong burning sensation, making it difficult to focus until\nthe effects have completely worn off.\n*Moderator Approved*\nImCookiie approved this item.", "minecraft:stone_sword", ""),
        StaticItem("Blue Willow Filigree Pin", "A small, pretty little pin in a plain oval\nshape! A broken china piece has been set upon\nthe filigree brass backing, giving the\nheirloom a dash of charm.", "minecraft:gold_nugget", ""),
        StaticItem("Orange Boots", "On the bottom of the boots the\nwords 'A. C.' would read.\n★Game Moderator Approved★\nSigned by Geoboy66.", "minecraft:leather_boots", ""),
        StaticItem("The Light Behind Your Eyes", "", "minecraft:written_book", ""),
        StaticItem("Knight's Luxurious Heater", "A well made and extravagant heater shield with a quality red paintjob.\nIt's leather strap appears to have small glowstone studs in it, making the handle glow\nin the dark, probably incase someone drops it in a dark place.\n*Moderator Approved*\nIrishPerson approved this item.", "minecraft:blaze_powder", ""),
        StaticItem("Candle of Light", "Given to those who arrived to Aethermoore’s\nvery first festival, this candle is a small\nlittle thing. The candle’s holder is of twisted gold,\nholding a beeswax candle within it.\nIts wick is unlit.", "minecraft:torch", ""),
        StaticItem("Eventide Crystal", "The crystal hums with energy, dots of darkness swimming inside the pale\nprism. Any void mage would notice a void of mana about the stone.", "minecraft:quartz", ""),
        StaticItem("Maiden's Reprieve", "The lute is highly elegant, it curving to fit the figure\nof a woman just right. Its wood is of a dark stain, a\nbeautiful deep and dark mahogany. If strung by those\nskilled of hand, it will produce a sound that strikes\nlonging into the hearts of even the manliest of men.\n*Moderator Approved*\nLifeforceIsMana approved this item.", "minecraft:fence", ""),
        StaticItem("Warped Stone", "A stone, rendered twisted and black by\nforbidden practices.\nIt feels otherworldly and strange to touch.\n★Game Moderator Approved★\nSigned by Wrynn.", "minecraft:obsidian", ""),
        StaticItem("Golem Voucher", "A voucher from the Stailinnord Company redeemable for one Golem! Seek Aengoth to redeem.\n((Speak to Aengoth or Bokratz))\n*Moderator Approved*\nAengoth approved this item.", "minecraft:paper", ""),
        StaticItem("Spider Silk", "", "minecraft:snow", ""),
        StaticItem("Ashes of Salei", "A gray ash rests within the urn.\n*Moderator Approved*\nPandann approved this item.", "minecraft:flower_pot", ""),
        StaticItem("Skull of Lewdness", "This mage-gold skull barks lewd remark towards\nanyone who holds it. The person who\ncreated this must have a vulgar sense of humor.\n*Moderator Approved*\nLifeforceIsMana approved this item.", "minecraft:skull", ""),
        StaticItem("Folded Painting", "A large portrait, creases formed within\nthe paper from being folded over and over\nagain. It would portray a nude Langon,\nhim posed oh so sexily. Signed in ink at\nthe bottom would be 'Lango'.", "minecraft:painting", ""),
        StaticItem("Lipstick", "A colored cosmetic applied to the lips from a small solid stick. TASTY!\n*Moderator Approved*\nFyaa approved this item.", "minecraft:dye", ""),
        StaticItem("Sceptre of light", "This ornate wand has a plethora of gold coiling\nalong the wooden shaft, trailing up to\nconjoin in the shape of four orcs that surround the\npearl on the top of the wood. With the\nflick of the wrist, the wand releases an extremely\nbright light-- perfect for blinding enemies, and\nfind your way in the dark!\n*Moderator Approved*\nLifeforceIsMana approved this item.", "minecraft:fire_charge", ""),
        StaticItem("Aspect Talisman", "This small talisman is finely crafted with\na metal base and some wooden inlay decorating\nthe talisman. Images of Cerridwen and Cernunnos\nare seen, holding an Oak sapling together in the\nmiddle of the talisman.\n★Game Moderator Approved★\nSigned by Wrynn.", "minecraft:iron_ingot", ""),
        StaticItem("Melody & Andrea", "A calendar, strikingly similar to the\nscum of the earth ones made before. This\none, however, would portray two oh-so hot\nlesbian brides, each month bringing some\nnew doofy pose. It begins in 1961 but\nends in 1962.\n★Game Moderator Approved★\nSigned by Begotten.", "minecraft:painting", ""),
        StaticItem("Colorful Pinwheel", "A small, fun little pinwheel. It portrays\nAethermoor's colors brilliantly; blue,\norange, and white. Inscribed upon its\nwooden handle would be tiny print,\nreading, \"The Rousing of Summer, 1961.", "minecraft:stick", ""),
        StaticItem("Aethermoore Coin", "The coin is of a coppery gold,\nAethermoore's lion imprinted into the metal.\nIt is said to bring good luck!", "minecraft:gold_nugget", ""),
        StaticItem("Bat Plushie", "A small black bat plush, made of\nsoft material with floppy wings.\n★Game Moderator Approved★\nSigned by Begotten.", "minecraft:leather", ""),
        StaticItem("Pig Plushie", "A pink little stuffed plush of a pig,\nmuch smaller and cleaner than the\nreal kind. Oinkoink!", "minecraft:leather", ""),
        StaticItem("Fruit Cake", "It is hard, decorative and most-likely unedible. Good paperweight though.\n*Moderator Approved*\nBrandNewKitten approved this item.", "minecraft:cake", ""),
        StaticItem("Ruibrium Tinted Cake", "The cake would be quite delicious, however tinted with\nthe highly addictive Ruibrium, ohmy.\n*Moderator Approved*\nPandann approved this item.", "minecraft:cake", ""),
        StaticItem("Elven Music Box", "A delicate little music box, small details carved into\naged wood. When opened, soft music would fill the air,\nmaking its listeners feel safe and at home.\n*Moderator Approved*\nLifeforceIsMana approved this item.", "minecraft:noteblock", ""),
        StaticItem("Spring Crown", "A crown made of pale ivory stone. It\nlooks as if leaves have been flawlessly\nwoven into the crown, bringing its\nwearers face to life. It recalls\nAethermoor’s Spring Leaf Festival in\n1560. Engraved into this particular crown\nwould be a tiny 'A&L'.", "minecraft:quartz", ""),
        StaticItem("Aethermoorian Lion Figure", "This figurine is finely crafted, using iron as a\nbase, but has gold decorating the figure. The\nlion would be standing upon a slab of stone,\nroaring at the sky.\n★Game Moderator Approved★\nSigned by Geoboy66.", "minecraft:gold_ingot", ""),
        StaticItem("Summoning Misfortune", "A book with unwritten pages. On the front is a large cycle with a big eye in the\nCenter. Underneath this Symbol is written 'Close your Hands, Close the eyes, Misfortune\nhere it Comes.\n*Moderator Approved*\nWrynn approved this item.", "minecraft:book", ""),
        StaticItem("Cernunnos Statue", "The quartz has been carefully chiseled into\nthe form of an imposing male with\nproud antlers, a bow in his hands strung\nwith a strand of silken thread.\nThe squared base he stands upon reads,\nCernunnos the Great Huntsman.\n★Game Moderator Approved★\nSigned by Begotten.", "minecraft:quartz_block", ""),
        StaticItem("Arrowhead Locket", "", "minecraft:ghast_tear", ""),
        StaticItem("Bouquet of Day Lilies", "A bouquet with colors as warm\nand bright as the summer's\nsun. Typically given to one\nwho could use a bit of cheer.", "minecraft:red_flower", ""),
        StaticItem("Ashen Skull", "A mask made from hardened clay and painted gray.\nSomething to surprise friends or startle enemies.\n★Game Moderator Approved★\nSigned by ImCookiie.", "minecraft:skull", ""),
        StaticItem("Toy Pirate Ship", "Arr! The toy pirate ship would be carved\nboth intricately, yet with a study nature\nin mind; seemingly good for your odd\ncollector, or simply a playful child.\nLittle blunt cutlass equipped figurines\nwould be found on the set.\n★Event Actor Approved★\nSigned by Murlocs.", "minecraft:acacia_boat", ""),
        StaticItem("Toy Pirate Figurines", "The carefully designed pirate wore\nsimilar bandanas and cutlasses alike. The\nsmall set of five dastardly crooks seemed\nto have individual appearances; quite\ndetailed as well.\n★Event Actor Approved★\nSigned by Murlocs.", "minecraft:dye", ""),
        StaticItem("Rag Doll", "This very small and cheap doll would be something for a peasant\nchild out on the streets of Felsen. Though it serves does work out in the end.\n*Moderator Approved*\nFyaa approved this item.", "minecraft:wheat", ""),
        StaticItem("Toy Viking Figurines", "The bearded set of three Northern raiders\nwore scars and axes alike; the giants\nshowing hearty expressions in their\ndelicately-carved form.\n★Event Actor Approved★\nSigned by Murlocs.", "minecraft:melon_seeds", ""),
        StaticItem("Skelt Shells", "Dark, shattered shells that seem fragile to the touch.\n*Moderator Approved*\nNalatac_Aicneta approved this item.", "minecraft:prismarine_shard", ""),
        StaticItem("Sprite Dust", "The dust seems to shimmer, seeming\nto give off a gentle glow.\n*Moderator Approved*\ndagothagahnim approved this item.", "minecraft:glowstone", ""),
        StaticItem("Book of protection", "The iron clad tome rests in your hand with utmost beauty.\nEach page produces a sense of amazing power...\nbut as you try to open the book, it keeps itself shut,\nprotecting itself from your prying hands.\n*Moderator Approved*\nLifeforceIsMana approved this item.", "minecraft:book", ""),
        StaticItem("Official Shogging Helm", "The helmet you wear whilst shogging.\n★Game Moderator Approved★\nSigned by Ever.", "minecraft:pumpkin", ""),
        StaticItem("Spooky Pumpkin Mask", "A mask of a pumpkin, it fitting easily\nover a broad variety of faces. A\ndevilish grin stretches upon it's face,\nstaring ahead scarily.\n*DO NOT PLACE DOWN*", "minecraft:pumpkin", ""),
        StaticItem("Gold Pendant", "This pendant grants oneself the flesh of a dark elf;\none whose eyes are sharp red and violet,\nand whom bears a faint beard of graying hairs\nonce black centuries before.", "minecraft:gold_nugget", ""),
        StaticItem("Golden Horens", "On one side of the coin, the face of Godfrey the Savior is clearly embossed.\nOn the other, the sigil of the First Oren Empire.", "minecraft:gold_nugget", ""),
        StaticItem("Hookah", "", "minecraft:brewing_stand", ""),
        StaticItem("Muttrock", "A roughly hewn canine made from a well-worn\nstone. It would be no larger than a chess\npiece, yet chiseled carefully enough to\nretain all of its details. The hound's pose\nis rigid as the stone it was carved from and\nit's muzzle appears to be thrown up into an\neverlasting howl.\n★Player Approved★\nSigned by OperationFuego.", "minecraft:stone", ""),
        StaticItem("The Staff of the Addled", "An intricate stave rests in your hand. Atop\nthe ornate head is a molten green cystal.\nAslong as you hold it you feel your grip on\nreality slipping, your senses numbing, as you\ndrift into a drinkless stupour. It's almost\nlike you're getting stupider!\n★Moderator Approved★\nSigned by Harrrison.", "minecraft:iron_hoe", ""),
        StaticItem("Catroot", "A strange, crudely feline-shaped root,\ngrown into an intricate braided motif in\nsome places. It lays, a bizarre sorrow to\nit, as if crafted by an artist in\nmourning. Its solemn gaze stares\never-watchful over those who hold it...\nPeering into their soul.\n★Player Approved★\nSigned by Gallic.", "minecraft:log", ""),
        StaticItem("๑ Nexus Shard ๑", "A shard of an irridescent substance. It glows\nbrightly when in contact with voidal magic.", "minecraft:stained_glass", ""),
        StaticItem("Light Green Boots", "On the side of the boots, there would be\nthe words, 'For your withered behind. May\nyou always be thwacking men upon the head\nwith cooking utensils' would be engraved.\n★Game Moderator Approved★\nSigned by Wrynn.", "minecraft:leather_boots", ""),
        StaticItem("Autumn Dust", "A nut-sized fire-opal nestled within a ring of\ntarnished silver, its iridescent hues of blue\nand red seemingly cast forever within the stone.\n*Moderator Approved*\nLifeforceIsMana approved this item.", "minecraft:dye", ""),
        StaticItem("Worn Handkerchief", "A soft, but used handkerchief embroidered\nwith patterns of swords and bows. The\nedges are frayed, and there's small\nspatters of blood on it. It smells very\nfaintly of lavender behind the strong\nreek of war.\n★Player Approved★\nSigned by Maidservant.", "minecraft:carpet", ""),
        StaticItem("Feather Duster", "An elegant feather duster of white\nfeathers and a black stained wooden\nhandle.\n★Player Approved★\nSigned by Maidservant.", "minecraft:feather", ""),
        StaticItem("Harpy Feather", "*Moderator Approved*\nJames27049 approved this item.\nThe feather of a slain Harpy, the feather is outlined with\nan ornate gold and black color.", "minecraft:feather", ""),
        StaticItem("Runic Key", "A small, seemingly ordinary key that would glow with runes inscribed upon it.\n*Moderator Approved*\nLifeforceIsMana approved this item.", "minecraft:gold_nugget", ""),
        StaticItem("Quartz Ring", "An elaborate ring of quartz carved to have\nthe appearance of many overlaying leaves.\n★Game Moderator Approved★\nSigned by JVQ.", "minecraft:quartz", ""),
        StaticItem("Washcloth", "A simple white washcloth with tattered\nedges, perfect for cleaning up spills or\ndirt.\n★Player Approved★\nSigned by Maidservant.", "minecraft:carpet", ""),
        StaticItem("Toy Sailor Figurines", "The set of four carved sailors wore\nsimilar uniforms to one another; proud\nexpressions written upon each individual\nface of the figurines. They were equipped\nwith swords and dirks amongst each other.\n★Event Actor Approved★\nSigned by Murlocs.", "minecraft:pumpkin_seeds", ""),
        StaticItem("Blight Charm", "A primal pendant, like roots entangling a\ncrude cut of naturally formed amber. Keeping\nit around seems to make the ills of unnatural\nblights feel just a little easier, and aid in\none's recovery from them... But, it won't\nsave you from more lethal cases. Either way,\nit's a pretty bauble.\n★Player Approved★\nSigned by Gallic.\n★Game Moderator Approved★\nSigned by Begotten.", "minecraft:gold_nugget", ""),
        StaticItem("Everlasting Candle", "The metal reinforced blackwood handle has a\ndim glow atop of it, neverfading through the\ndarkest of nights of the rainiest of days. No\nfuel is required to use it.\n★Moderator Approved★\nSigned by Harrrison.", "minecraft:torch", ""),
        StaticItem("The Spooniest of Spoons", "A long wooden spoon. It brings with it\nmemories of warm, freshly baked chocolate\nchip cookies, as well as a few angered\nbeatings.", "minecraft:stick", ""),
