    private fun _AXIOS_ASUL_7(): List<StaticItem> = listOf(
        StaticItem("Crab Shell", "A hard encasing, seeming to be quite sturdy\nand surprisingly light.\n★Game Moderator Approved★\nSigned by cyber_king3.", "minecraft:leather", ""),
        StaticItem("==- Champion's Sparring Blade -==", "A sparring blade rewarded to the winner of\nthe Dreadlands Peasant Fair tourney. The\nblade made of an uknown wood, albeit thick\nand dull this weapon seemed almost completely\ninvulnerable to the wear and tear of battle;\na perfect weapon to use for practice.\n★Game Moderator Approved★\nSigned by The Champion.", "minecraft:wooden_sword", ""),
        StaticItem("Man Removal Spike", "A boar spear of five feet in total length,\naurum headed with small 'wings' just below\nit. The spearhead, when met with mortal\nflesh, would erode it like acid might, and\nproducing a thin black taint to lay in the\nwound and over the blade for further assault.\n★Event Actor Approved★\nSigned by DoctorGoosey.", "minecraft:golden_shovel", ""),
        StaticItem("Golden Coin", "A gold coin with a golden chalice on it. Its\nbent, very dirty, and rusted.\n★Event Actor Approved★\nSigned by Ateegahofawsome.", "minecraft:gold_nugget", ""),
