        StaticItem("Ornate Hairbrush", "An ornate brush for arranging or smoothing a\nperson's hair. This one is made of a\nhighly-polished golden handle and stiff horse\nhair for the bristles.\n★Player Approved★\nSigned by Hobbes & Schmick Formal Outfitters.", "minecraft:gold_ingot", ""),
        StaticItem("Ash Insignia", "A drawing of an ash tree, made in charcoal.\nIn the corner of your eye, the branches seem\nto writhe.", "minecraft:filled_map", ""),
